(function(){'use strict';const E=window.NavigatorEvidence;if(!E)return;let record=E.create(),context={stage:'P01'},selected='';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=document.createElement('details');panel.id='g-evidence-panel';panel.className='g-panel';panel.innerHTML='<summary><strong>Evidence and report annexures</strong> <span id="evidence-count" class="g-mini"></span></summary><p>Use neutral labels such as “Chat extract” or “CCTV clip”, issue codes and secure record references only. No files, testimony, identities or evidence contents are uploaded or stored on a server. Save your recovery file to retain this index.</p><p>If an item was received after recorded inquiry completion or report submission, obtain a competent procedural direction before incorporating it. Keep later material separate from the concluded report where required. Do not backdate records or assume that time limits reset. Numbers are proposed administrative references, not formal admission, authentication or statutory exhibit marks. Confirm the Committee’s marking and actual attachments before report authorisation. Reserved numbers are never silently reused. Check for clashes with existing institutional marks before approving a proposed reference; record any prior marking in the review reference.</p><div class="evidence-grid"><label>Reviewer code<input id="evidence-actor" maxlength="100" placeholder="Committee reviewer code"></label><label>Change reason or record reference<input id="evidence-reason" maxlength="200" placeholder="Reason / direction reference"></label></div><label for="evidence-select">Item to record or correct</label><select id="evidence-select"><option value="">New item</option></select><form id="evidence-form"><div class="evidence-grid"><label>Neutral evidence label<input name="label" maxlength="100" required placeholder="Chat extract / CCTV clip"></label><label>Material type<select name="kind"><option value="chat">Chat / message</option><option value="cctv">CCTV / video</option><option value="email">Email</option><option value="document">Document</option><option value="audio">Audio</option><option value="other">Other</option></select></label><label>Source or receipt record reference<input name="sourceRef" maxlength="160"></label><label>Actual receipt date, if known<input name="received" type="date"></label><label>Relevant issue codes, if applicable<input name="issueRefs" maxlength="160" placeholder="A01, A02 — no narratives"></label><label>Custody / original-location reference<input name="custodyRef" maxlength="160"></label></div><section id="evidence-review-fields" hidden><details><summary>Marking, source and integrity review</summary><label>If receipt date is unknown or disputed: review / direction reference<input name="receiptReviewRef" maxlength="160"></label><p class="g-mini">Do not invent a date to clear a control. Record the uncertainty and competent review reference; this does not reset any timeline trigger.</p><label><input name="markApproved" type="checkbox"> Committee review of this proposed annexure mark recorded</label><label>Marking review / direction reference<input name="markRef" maxlength="160"></label><label>Source and integrity review<select name="integrity"><option value="pending">Not yet reviewed</option><option value="review_recorded">Review recorded</option></select></label><label>Integrity / preservation review reference<input name="integrityRef" maxlength="160"></label><p class="g-mini">For electronic material, preserve original files, context, timestamps and the collection/custody record. Verify the applicable process and any authentication or certificate issue. Distinguish duplicate copies from independent material. A label, screenshot or file fingerprint does not prove authenticity.</p></details><details><summary>Disclosure, participation and objections</summary><div class="evidence-grid"><label>Disclosure status<select name="disclosure"><option value="pending">Review pending</option><option value="provided">Applicable disclosure recorded</option><option value="protective_direction">Protective direction recorded — verify legality</option></select></label><label>Disclosure / direction reference<input name="disclosureRef" maxlength="160"></label><label>Response opportunity<select name="opportunity"><option value="pending">Review pending</option><option value="recorded">Opportunity recorded</option><option value="direction_recorded">Reasoned procedural direction recorded</option></select></label><label>Opportunity / direction reference<input name="opportunityRef" maxlength="160"></label><label>Objections or disputes<select name="objection"><option value="not_reviewed">Not yet reviewed</option><option value="none_recorded">No objection recorded after review</option><option value="pending">Objection unresolved</option><option value="addressed">Objection addressed by recorded direction</option></select></label><label>Objection / decision reference<input name="objectionRef" maxlength="160"></label></div><p class="g-mini">A protected route is not a waiver of fair opportunity. Record the actual competent direction; the app does not approve a restriction, decide admissibility or presume consent from silence.</p></details><details><summary>Report use, attachment and follow-up</summary><div class="evidence-grid"><label>Committee’s recorded use assessment<select name="use"><option value="pending">Assessment pending</option><option value="relied_on">Recorded as relied on</option><option value="not_relied_on">Recorded as not relied on</option></select></label><label>Analysis / reasons record reference<input name="useRef" maxlength="160"></label><label>Actual attachment / controlled-location status<select name="attachment"><option value="pending">Not verified</option><option value="attached">Attachment verified</option><option value="not_attached">Not attached — verify reason / direction</option></select></label><label>Page range, file-location or direction reference<input name="attachmentRef" maxlength="160"></label><label>Responsible follow-up owner code<input name="owner" maxlength="160"></label><label>Personal follow-up review date<input name="followupDue" type="date"></label></div><p class="g-mini">Record why supporting and contrary material is relied on or not relied on in the actual Committee record. Record the applicable disclosure and participation review for non-relied-on material too; an exclusion must not silently bypass fairness checks. These reference fields are not findings or testimony. A personal review date does not change a statutory period.</p></details></section><div class="g-button-row"><button class="g-btn" type="submit" id="evidence-save">Add evidence reference</button><button class="g-btn secondary" type="button" id="evidence-new">Record another item</button></div></form><p id="evidence-status" role="status" class="g-mini"></p><section id="evidence-readiness" aria-label="Evidence review gaps"></section><div id="evidence-list"></div><div class="g-button-row"><button type="button" class="g-btn secondary" id="evidence-index-download">Download annexure index</button><button type="button" class="g-btn secondary" id="evidence-report-download">Prepare report with current references</button></div><details><summary>Index history and legal basis</summary><p>History is a local review trail, not a tamper-proof institutional record. Imported entries are untrusted until checked against originals. The Committee retains the official evidence, directions and signed report.</p><p>Review applicable service/sector rules, Section 11 powers and procedure, Central Rule 7 natural justice where applicable, and Section 16 confidentiality. No universal statutory numbering syntax is asserted by this tool. Legal outcomes and appeals remain subject to the applicable law. <a href="https://nhrc.nic.in/assets/uploads/training_projects/NHRC_Study_rpt_sexual_harrasemnt_workplaceDec2023.pdf#page=194" target="_blank" rel="noopener">Reproduced Act</a> · <a href="https://spniwcd.wcd.gov.in/uploads/pdf/1719914401_2NUqe91gql.pdf#page=2" target="_blank" rel="noopener">Official Central Rules</a></p><div id="evidence-history"></div></details>';
$('g-timeline-panel').before(panel);const f=$('evidence-form');
function values(){return Object.fromEntries(E.fields.map(k=>[k,f.elements[k].type==='checkbox'?f.elements[k].checked:f.elements[k].value]));}
function setValues(v){for(const k of E.fields){const field=f.elements[k];if(field.type==='checkbox')field.checked=!!v[k];else field.value=v[k]??'';}}
function message(text,error=false){$('evidence-status').textContent=text;$('evidence-status').className=error?'g-alert':'g-mini';}
function item(){return record.items.find(x=>x.id===selected);}
function load(id){selected=id;const value=item();setValues(value||E.defaults());$('evidence-select').value=id;$('evidence-review-fields').hidden=!value;$('evidence-save').textContent=value?'Record correction / review':'Add evidence reference';}
function visibility(){const n=Number(String(context.stage).slice(1));panel.hidden=!record.items.length&&!(String(context.stage).startsWith('P')&&n>=13);}function render(){visibility();const result=E.review(record,undefined,window.NavigatorTimelineUI?.getDates()||{});$('evidence-count').textContent=record.items.length?'· '+record.items.length+' item(s), '+result.pending.length+' with checks pending':'';$('evidence-select').innerHTML='<option value="">New item</option>'+record.items.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.annexure+' — '+x.label+(x.active?'':' (withdrawn)'))+'</option>').join('');$('evidence-select').value=selected;$('evidence-readiness').innerHTML=!record.items.length?'<p>No evidence references recorded. This is not a statement that the proceeding contains no evidence.</p>':result.pending.length?'<h3>Review before final report completion</h3><ul>'+result.pending.map(x=>'<li><strong>'+esc(x.annexure+' — '+x.label)+'</strong>: '+esc(x.gaps.join('; '))+'. <strong>'+esc(x.followupStatus)+'</strong>. '+esc(x.owner?'Owner '+x.owner:'Assign an owner')+'; '+esc(x.followupDue?'review '+x.followupDue:'set a review date')+'. <button type="button" class="g-btn secondary" data-evidence-edit="'+esc(x.id)+'">Review this item</button></li>').join('')+'</ul>':'<p class="g-soft">No index-control gap is flagged. Independently verify records and the report; this is not certification of legal compliance.</p>';$('evidence-list').innerHTML='<ul class="evidence-cards">'+record.items.map(x=>'<li><strong>'+esc('Annexure '+x.annexure)+' — '+esc(x.label)+'</strong><p>'+esc(x.active?'Active reference':'Withdrawn; number reserved')+' · '+esc(x.markApproved?'Mark review recorded':'Proposed mark')+' · '+esc(x.issueRefs||'No issue code recorded')+'</p><div class="g-button-row"><button type="button" class="g-btn secondary" data-evidence-edit="'+esc(x.id)+'">Review or correct</button><button type="button" class="g-btn secondary" data-evidence-active="'+esc(x.id)+'">'+(x.active?'Withdraw from active index':'Restore to active index')+'</button></div></li>').join('')+'</ul>';$('evidence-history').innerHTML=record.audit.map(x=>'<p>'+esc(x.at)+' · '+esc(x.actor)+' · '+esc({add:'Reference added',update:'Correction / review',active:'Active status changed'}[x.command.type]||x.command.type)+' · '+esc(x.reason)+'</p>').join('');$('evidence-index-download').disabled=!record.items.length;$('evidence-report-download').disabled=!record.items.length;}
function apply(command){if(document.querySelector('.g-shell')?.inert)throw Error('Verify account access before changing the index.');record=E.change(record,command,$('evidence-actor').value,$('evidence-reason').value);render();window.dispatchEvent(new CustomEvent('navigator:evidence-changed'));document.dispatchEvent(new Event('input',{bubbles:true}));}
f.onsubmit=e=>{e.preventDefault();try{const all=values(),prior=item(),changed=prior?Object.fromEntries(Object.entries(all).filter(([k,v])=>v!==prior[k])):all;if(prior&&!Object.keys(changed).length){message('No changed fields to record.');return;}apply(prior?{type:'update',id:selected,fields:changed}:{type:'add',fields:changed});load(prior?selected:record.items[record.items.length-1].id);message('Reference recorded locally. No evidence was admitted, filed, served or evaluated by the software. Save recovery before closing.');}catch(e){message(e.message,true);}};
function formDirty(){const base=item()||E.defaults();return E.fields.some(k=>values()[k]!==base[k]);}function choose(id){if(formDirty()&&!confirm('Discard unrecorded evidence form changes? Record them first if needed.')){$('evidence-select').value=selected;return;}load(id);} $('evidence-select').onchange=e=>choose(e.target.value);$('evidence-new').onclick=()=>{choose('');f.elements.label.focus();};panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.evidenceEdit){choose(b.dataset.evidenceEdit);f.elements.label.focus();}if(b.dataset.evidenceActive){const i=record.items.find(x=>x.id===b.dataset.evidenceActive);if(!confirm((i.active?'Withdraw':'Restore')+' this reference? Its number and history remain.'))return;apply({type:'active',id:i.id,active:!i.active});load(i.id);}}catch(e){message(e.message,true);}});
function download(report){try{if(formDirty())throw Error('Record or discard unsubmitted evidence fields before preparing the document. They are not yet part of the index.');if(document.querySelector('.g-shell')?.inert)throw Error('Verify account access before preparing a new document.');const id=report?'inquiry-report':'evidence-register';if(!window.NavigatorTimelineUI.recordDocument(id,{actor:$('evidence-actor').value.trim()||'Unidentified session reviewer',reason:'Working '+(report?'report and annexure':'annexure index')+' draft requested; no findings or service recorded'}))throw Error('Draft request could not be logged.');const items=report?window.PoshWorkflowDocuments.items(id,window.NavigatorTimelineUI.getDates()):[{type:'title',text:'Evidence and annexure index'},...E.reportItems(record,window.NavigatorTimelineUI?.getDates()||{}).slice(1)];window.NavigatorDocx.download(report?'POSH_Inquiry_Report_With_Annexure_References.docx':'POSH_Evidence_Annexure_Index.docx',window.NavigatorPersonalDocx.buildDocx(report?'Committee inquiry report':'Evidence and annexure index',items,report?{workflow:true}:{personal:true,workflow:true}));message('Working document download requested. Review unresolved checks and actual attachments before authorisation.');}catch(e){message(e.message,true);}}
$('evidence-index-download').onclick=()=>download(false);$('evidence-report-download').onclick=()=>download(true);
function snapshot(){return {record:JSON.parse(JSON.stringify(record)),form:{selected,actor:$('evidence-actor').value,reason:$('evidence-reason').value,fields:values()}};}
function prepareRestore(data){if(data===undefined)return()=>{record=E.create();selected='';$('evidence-actor').value='';$('evidence-reason').value='';render();load('');window.dispatchEvent(new CustomEvent('navigator:evidence-changed'));};if(!data||Object.keys(data).some(k=>!['record','form'].includes(k))||!data.form||Object.keys(data.form).some(k=>!['selected','actor','reason','fields'].includes(k)))throw Error('Invalid evidence recovery fields.');const restored=E.restore(data.record),d=data.form;if(typeof d.selected!=='string'||d.selected&&!restored.items.some(x=>x.id===d.selected)||typeof d.actor!=='string'||d.actor.length>100||typeof d.reason!=='string'||d.reason.length>200||!d.fields||Object.keys(d.fields).length!==E.fields.length||E.fields.some(k=>!Object.hasOwn(d.fields,k)))throw Error('Invalid evidence form draft.');for(const k of E.fields){const v=d.fields[k];if(k==='markApproved'?typeof v!=='boolean':typeof v!=='string'||v.length>(k==='label'?100:160)||/[<>\u0000-\u001f]/.test(v))throw Error('Invalid unsubmitted evidence field.');if(E.choices[k]&&!E.choices[k].includes(v))throw Error('Unknown evidence draft status.');if(['received','followupDue'].includes(k)&&v&&!E.date(v))throw Error('Invalid evidence draft date.');}return()=>{record=restored;selected=d.selected;$('evidence-actor').value=d.actor;$('evidence-reason').value=d.reason;render();load(selected);setValues(d.fields);message('Restored index and unsubmitted fields locally. Check every reference against institutional originals before relying on it.');window.dispatchEvent(new CustomEvent('navigator:evidence-changed'));};}
window.NavigatorEvidenceUI={encodeDocument:(id,title,items)=>record.items.length&&['inquiry-report','evidence-register','findings-matrix'].includes(id)?window.NavigatorPersonalDocx.buildDocx(title,items,{personal:true,workflow:true}):null,snapshot,prepareRestore,record:()=>JSON.parse(JSON.stringify(record)),hasBlockingGaps:()=>E.review(record,undefined,window.NavigatorTimelineUI?.getDates()||{}).pending.length>0,open:()=>{panel.hidden=false;panel.open=true;panel.scrollIntoView({block:'start'});$('evidence-select').focus();},setContext:value=>{context=value;visibility();},forDocument:(id,items)=>['inquiry-report','evidence-register','findings-matrix'].includes(id)&&record.items.length?[...items,...E.reportItems(record,window.NavigatorTimelineUI?.getDates()||{})]:items};
const shortcut=document.createElement('button');shortcut.type='button';shortcut.className='g-btn secondary';shortcut.textContent='Open evidence and annexure index';shortcut.onclick=()=>window.NavigatorEvidenceUI.open();$('g-documents').before(shortcut);render();load('');panel.hidden=true;window.addEventListener('navigator:timeline-changed',render);const timer=setInterval(()=>{if(!document.contains(panel)){clearInterval(timer);return;}render();},60000);
})();
